#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BracketRole {
    Closer,
    Opener,
}

/// Bracket opener/closer role for depth-tracking token scans
/// (`skip_where_clause`, `rhs_is_sum` in `parse_parser_body.txt`).
/// Authored as `bracket_*: BracketRow` rows in
/// `src/v3/compiler/parse_tables.dag`; regenerated by `regen_parse_tables`.
pub fn bracket_role(kind: &TokenKind) -> Option<BracketRole> {
    match kind {
        TokenKind::LBrace => Some(BracketRole::Opener),
        TokenKind::LBracket => Some(BracketRole::Opener),
        TokenKind::LParen => Some(BracketRole::Opener),
        TokenKind::RBrace => Some(BracketRole::Closer),
        TokenKind::RBracket => Some(BracketRole::Closer),
        TokenKind::RParen => Some(BracketRole::Closer),
        _ => None,
    }
}

